#!/usr/bin/env python3
import base64, io, json, re, sys
from pathlib import Path
from urllib.parse import urlencode, quote
import requests
from PIL import Image, ImageOps

S=requests.Session()
S.headers.update({'User-Agent':'AdOrientemReferenceResearch/0.1 (contact via github.com/Fulcanelli13/ad-orientem)','Accept':'application/json,image/*'})
GROUPS=[["mass","The Traditional Roman Mass — priest and altar",[["Gospel chanted, St John Cantius","The Holy Mass celebrated according to the 1962 Missal at St. John Cantius Church in Chicago 1.jpg"],["Priest offering Mass, St John Cantius","The Holy Mass celebrated according to the 1962 Missal at St. John Cantius Church in Chicago 2.jpg"],["Confiteor, traditional Solemn Mass","Confiteor at Tridentine Mass.jpg"],["Priest at altar, Tridentine Confiteor","TridentineConfiteor.jpg"],["Priest at altar, Tridentine Epistle","TridentineEpistle.jpg"],["Priest at altar, Tridentine Gospel","TridentinGospel.jpg"],["Offertory at traditional Mass","TridentinOffertory.jpg"],["Consecration at traditional Mass","TridentineConsecration.jpg"],["Elevation at traditional Mass","Traditional Latin Mass - Elevation.jpg"],["Elevation of the Host","Elevation of the Host.jpg"],["Elevation at Solemn High Mass","Elevation of the Host in the Solemn High Mass.jpg"],["Elevation of Precious Blood","Elevation of Sacred Blood (15783072803).jpg"],["Consecration and elevation","Consecration Elevation Holy Mass.jpg"],["Communion – Ecce Agnus Dei","Ecce Agnus Dei.jpg"],["Traditional Leonine Prayers","Traditional Latin Mass - Leonine Prayers.jpg"],["Last Gospel","The Last Gospel.JPG"],["Traditional Mass – Reims 2019 (1)","Reims - Église Sainte-Jeanne-d’Arc - messe en présence de Mgr Éric de Moulins-Beaufort - septembre 2019 - 1.jpg"],["Traditional Mass – Reims 2019 (2)","Reims - Église Sainte-Jeanne-d’Arc - messe en présence de Mgr Éric de Moulins-Beaufort - septembre 2019 - 2.jpg"],["Traditional Mass – Reims 2019 (3)","Reims - Église Sainte-Jeanne-d’Arc - messe en présence de Mgr Éric de Moulins-Beaufort - septembre 2019 - 3.jpg"]]],["ceremonies","TLM ceremonies, ministers and special Masses",[["Tridentine Mass, Strasbourg Cathedral","Tridentine Mass in Strasbourg Cathedral.JPG"],["Strasbourg Requiem 2013 — frame 04","Strasbourg crypte de la cathédrale Notre Dame messe de Requiem 2013 04.JPG"],["Strasbourg Requiem 2013 — frame 05","Strasbourg crypte de la cathédrale Notre Dame messe de Requiem 2013 05.JPG"],["Strasbourg Requiem 2013 — frame 06","Strasbourg crypte de la cathédrale Notre Dame messe de Requiem 2013 06.jpg"],["Strasbourg Requiem 2013 — frame 08","Strasbourg crypte de la cathédrale Notre Dame messe de Requiem 2013 08.JPG"],["Traditional Mass, Prague 1","TLM at Church of the Assumption in Prague 1.jpg"],["Traditional Mass, Prague 2","TLM at Church of the Assumption in Prague 2.jpg"],["Traditional Mass, Koenji Japan — 1","Tridentine Mass Koenji 2026-07-05.1.jpg"],["Traditional Mass, Koenji Japan — 2","Tridentine Mass Koenji 2026-07-05.2.jpg"],["Traditional Mass, Koenji Japan — 3","Tridentine Mass Koenji 2026-07-05.jpg"],["Traditional Mass, Dobrš Easter 2009","Dobrš, Velikonoce 2009, tridentská mše (17).jpg"],["Traditional Mass, Dobrš Easter 2010 — 09","Dobrš, Velikonoce 2010, tridentská mše (09).jpg"],["Traditional Mass, Dobrš Easter 2010 — 10","Dobrš, Velikonoce 2010, tridentská mše (10).jpg"],["Traditional Mass, Dobrš Easter 2010 — 14","Dobrš, Velikonoce 2010, tridentská mše (14).jpg"],["Solemn Pontifical Mass, Zagreb 2026","Solemn Pontifical Mass in Zagreb 2026 celebrated by archbishop Salvatore Cordileone.jpg"],["TLM in Milton Keynes","Traditionelle lateinische Messe mit Athanasius Schneider in Milton Keynes.jpg"],["Traditional Mass, Prostějov","High Tridentine Mass Prostějov 2023.png"],["TLM Nuptial Mass","TLM pro sponsis.jpg"]]],["sequence","TLM consecration — one continuous photographic sequence (Reims 2023)",[["Reims 2023 consecration sequence — 04","Reims - église Notre-Dame-de-France - 2023-12-07 - consécration et élévation - 4.jpg"],["Reims 2023 consecration sequence — 12","Reims - église Notre-Dame-de-France - 2023-12-07 - consécration et élévation - 12.jpg"],["Reims 2023 consecration sequence — 22","Reims - église Notre-Dame-de-France - 2023-12-07 - consécration et élévation - 22.jpg"],["Reims 2023 consecration sequence — 30","Reims - église Notre-Dame-de-France - 2023-12-07 - consécration et élévation - 30.jpg"],["Reims 2023 consecration sequence — 38","Reims - église Notre-Dame-de-France - 2023-12-07 - consécration et élévation - 38.jpg"],["Reims 2023 consecration sequence — 46","Reims - église Notre-Dame-de-France - 2023-12-07 - consécration et élévation - 46.jpg"],["Reims 2023 consecration sequence — 54","Reims - église Notre-Dame-de-France - 2023-12-07 - consécration et élévation - 54.jpg"],["Reims 2023 consecration sequence — 60","Reims - église Notre-Dame-de-France - 2023-12-07 - consécration et élévation - 60.jpg"]]],["settings","Traditional Catholic church environments — TLM venue, not necessarily Mass shown",[["Santissima Trinità dei Pellegrini — nave","TrinitaNavata.jpg"],["Santissima Trinità — high altar","TrinitaAltare.jpg"],["Santissima Trinità — high altar red","Altare Maggiore - Rosso.jpg"],["Santissima Trinità — Paschal altar","Santissima Trinità dei Pellegrini - Altare Maggiore - Pasqua.jpg"],["Santissima Trinità — sacristy","Trinita PellegriniSacristy.jpg"],["Santissima Trinità — side altar","TrinitaPellegriniSideAltar1.jpg"],["Santissima Trinità — Holy Cross","TrinitaPellegriniHolyCross.jpg"],["St John Cantius, Chicago interior","St. John Cantius Church in Chicago interior.jpg"],["Saint Eugène Sainte Cécile — interior","Intérieur de l'église Saint-Eugène-Sainte-Cécile.jpg"]]],["objects","1962 altar furnishings — liturgical object references",[["Three altar cards","Catholic Picture Dictionary (Pfeiffer) - Altar cards.jpg"],["Traditional altar card, Benzinger","Benzinger altar card center HD.jpg"],["Traditional altar card set","Arte veneziana, corredo di cartegloria, 1678-1736 ca.jpg"]]]]

names=list(dict.fromkeys(f for k,t,lst in GROUPS for label,f in lst))
p={'action':'query','format':'json','formatversion':'2','prop':'imageinfo','iiprop':'url|mime|extmetadata',
   'iiurlwidth':600,'titles':'|'.join('File:'+n for n in names)}
u='https://commons.wikimedia.org/w/api.php?'+urlencode(p)
res=S.get(u,timeout=45); print('API:',res.status_code,len(res.content),res.text[:180],flush=True);res.raise_for_status()
info={x.get('title','').removeprefix('File:'):(x.get('imageinfo')or[{}])[0]
 for x in res.json()['query']['pages'] if 'missing' not in x}
print('API matched',len(info),'of',len(names),flush=True)
def value(thing):
 return re.sub('<[^>]*>','',thing.get('value','')) if isinstance(thing,dict) else ''
images={};missing=[]
for n in names:
 item=info.get(n)
 if not item:
  print('MISSING title',n,flush=True);missing.append([n,'missing API title']);continue
 for url in [item.get('thumburl'),item.get('url')]:
  if not url:continue
  try:
   rr=S.get(url,timeout=28);rr.raise_for_status()
   im=Image.open(io.BytesIO(rr.content));im.load()
   if im.width<120 or im.height<120:raise ValueError('small image')
   im=ImageOps.exif_transpose(im).convert('RGB');im.thumbnail((720,650),Image.Resampling.LANCZOS)
   b=io.BytesIO();im.save(b,format='JPEG',quality=74,optimize=True)
   ext=item.get('extmetadata')or{}
   images[n]={'data':'data:image/jpeg;base64,'+base64.b64encode(b.getvalue()).decode(),
      'url':'https://commons.wikimedia.org/wiki/File:'+quote(n.replace(' ','_'),safe='()'),
      'license':value(ext.get('LicenseShortName',{})),'artist':value(ext.get('Artist',{}))[:100],
      'size':list(im.size),'filename':n}
   print('OK',n,len(b.getvalue()),flush=True)
   break
  except Exception as e:
   err=str(e);print('URL failure',n,err[:150],flush=True)
 if n not in images:missing.append([n,err])
payload=[]
for k,title,items in GROUPS:
 c=[{'id':k+'/'+name,'title':label,**images[name]} for label,name in items if name in images]
 if c:payload.append({'key':k,'title':title,'items':c})
total=sum(len(x['items']) for x in payload)
print('TOTAL VERIFIED',total,'FAILURES',len(missing),flush=True)
if total<20:raise RuntimeError('Insufficient verified TLM images for review.')
page=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Visible Mass — Curated reference photographs</title>
<style>:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#080d12;color:#e9e3d9;font:15px Georgia,serif}header{padding:18px;position:sticky;top:0;background:#080d12ed;border-bottom:1px solid #48505a;z-index:5}h1{font-size:21px;letter-spacing:.05em;font-weight:normal;margin:0 0 8px}p,small{color:#b2b6ba}main{max-width:1520px;margin:auto;padding:14px}section{margin:15px 0 35px}h2{font-size:18px;font-weight:normal}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(275px,1fr));gap:14px}.card{background:#151d26;border:1px solid #3e4954;border-radius:9px;overflow:hidden}.image{height:255px;background:black}.image img{width:100%;height:100%;object-fit:contain;cursor:zoom-in}.info{padding:12px}.info h3{font-size:15px;margin:0 0 6px}.row{display:flex;flex-wrap:wrap;gap:6px;margin:10px 0}.score{background:#232d37;border:1px solid #586370;color:#eee;border-radius:5px;cursor:pointer;padding:7px 10px}.score.sel{background:#d0b081;color:#111}select,button,textarea{font:13px system-ui,sans-serif}select,textarea{background:#202b37;color:#eee;border:1px solid #566270;border-radius:6px;padding:8px}textarea{width:100%;height:50px;resize:vertical;margin-top:7px}a{color:#d9bd93}.meta{font:11px/1.5 system-ui,sans-serif;color:#b3bbc5}.controls{display:flex;gap:8px;flex-wrap:wrap}.controls select,.controls button{border:1px solid #53606b;background:#1b2631;color:#eee;border-radius:5px;padding:8px;cursor:pointer}.controls span{font:12px system-ui,sans-serif;color:#b3bbc5;align-self:center}#overlay{position:fixed;inset:0;background:#000e;z-index:20;display:none;align-items:center;justify-content:center}#overlay.visible{display:flex}#overlay img{max-width:98vw;max-height:95vh;object-fit:contain}#overlay button{position:absolute;top:12px;right:12px;padding:10px}</style></head><body>
<header><h1>The Visible Mass · TLM photographic curation</h1><small>Traditional Latin Mass / 1962 Roman Missal reference review. Verified Commons images embedded for offline browsing. Rank, rate, and export.</small>
<div class="controls"><select id="filter"><option value="all">All categories</option></select><select id="order"><option value="source">Source order</option><option value="rank">Your priority rank</option><option value="score">Your highest scores</option></select><select id="rated"><option value="all">All photographs</option><option value="unrated">Unrated only</option><option value="rated">Rated only</option></select><button id="json">Export JSON</button><button id="csv">Export CSV</button><span id="progress"></span></div></header>
<main id="main"></main><div id="overlay"><img id="enlarged"><button id="close">Close</button></div>
<script type="application/json" id="payload">__PAYLOAD__</script><script>
const D=JSON.parse(document.getElementById('payload').textContent);
const ALL=D.flatMap(g=>g.items);
const STORAGE='ao_visible_mass_tlm_photos_v1';let R={};try{R=JSON.parse(localStorage.getItem(STORAGE)||'{}')}catch(e){}
const el=id=>document.getElementById(id), E=x=>String(x||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/"/g,'&quot;');
function save(){try{localStorage.setItem(STORAGE,JSON.stringify(R))}catch(e){}progress()}
function progress(){let n=D.reduce((a,c)=>a+c.items.length,0);el('progress').textContent=Object.values(R).filter(v=>v.score!==undefined).length+' / '+n+' rated'}
function makeCard(it){let r=R[it.id]||{};let art=document.createElement('article');art.className='card';
let imgbox=document.createElement('div');imgbox.className='image';let img=new Image();img.src=it.data;img.loading='lazy';img.alt=it.title;
img.onclick=()=>{el('enlarged').src=it.data;el('overlay').classList.add('visible')};imgbox.append(img);art.append(imgbox);
let info=document.createElement('div');info.className='info';let h=document.createElement('h3');h.textContent=it.title;info.append(h);
let scores=document.createElement('div');scores.className='row';[0,1,2,3,4,5].forEach(n=>{let b=document.createElement('button');b.textContent=n;b.className='score'+(r.score===n?' sel':'');b.onclick=()=>{R[it.id]??={};R[it.id].score=n;save();scores.querySelectorAll('button').forEach(bb=>bb.classList.toggle('sel',bb===b))};scores.append(b)});info.append(scores);
let priority=document.createElement('label');priority.className='meta';priority.textContent='Your overall priority rank (1 = highest): ';let pn=document.createElement('input');pn.type='number';pn.min=1;pn.max=999;pn.placeholder='–';pn.style.cssText='width:68px;background:#202b37;color:white;border:1px solid #566270;border-radius:5px;padding:6px;';pn.value=r.rank??'';pn.onchange=()=>{R[it.id]??={};if(pn.value) R[it.id].rank=Number(pn.value);else delete R[it.id].rank;save();draw()};priority.append(pn);info.append(priority);
let fit=document.createElement('select');[['this','Suitable here'],['elsewhere','Useful elsewhere'],['reject','Reject']].forEach(x=>{let o=document.createElement('option');o.value=x[0];o.textContent=x[1];fit.append(o)});fit.value=r.fit||'this';fit.onchange=()=>{R[it.id]??={};R[it.id].fit=fit.value;save()};info.append(fit);
let notes=document.createElement('textarea');notes.placeholder='Notes';notes.value=r.notes||'';notes.oninput=()=>{R[it.id]??={};R[it.id].notes=notes.value;save()};info.append(notes);
let meta=document.createElement('div');meta.className='meta';meta.textContent=(it.artist||'Commons contributor')+' · '+(it.license||'Check licence')+' · ';let link=document.createElement('a');link.href=it.url;link.textContent='Open original & licence';link.target='_blank';link.rel='noopener';meta.append(link);info.append(meta);art.append(info);return art}
function draw(){let k=el('filter').value, order=el('order').value, rated=el('rated').value;el('main').replaceChildren();D.filter(g=>k==='all'||g.key===k).forEach(g=>{let items=g.items.filter(it=>rated==='all'||(rated==='rated')===(R[it.id]?.score!==undefined));if(order==='rank')items.sort((a,b)=>(R[a.id]?.rank||9999)-(R[b.id]?.rank||9999));if(order==='score')items.sort((a,b)=>(R[b.id]?.score??-1)-(R[a.id]?.score??-1));if(!items.length)return;let sec=document.createElement('section');let h=document.createElement('h2');h.textContent=g.title+' ('+items.length+')';sec.append(h);let gr=document.createElement('div');gr.className='grid';items.forEach(it=>gr.append(makeCard(it)));sec.append(gr);el('main').append(sec)});progress()}
D.forEach(g=>{let o=document.createElement('option');o.value=g.key;o.textContent=g.title+' ('+g.items.length+')';el('filter').append(o)});el('filter').onchange=draw;el('order').onchange=draw;el('rated').onchange=draw;
el('close').onclick=()=>el('overlay').classList.remove('visible');el('overlay').onclick=e=>{if(e.target===el('overlay'))el('close').click()};document.addEventListener('keydown',e=>{if(e.key==='Escape')el('close').click()});
function download(name,body,type){let u=URL.createObjectURL(new Blob([body],{type}));let a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),2000)}
el('json').onclick=()=>download('visible-mass-tlm-rankings.json',JSON.stringify({format:'AO_VISIBLE_MASS_TLM_RANKINGS_V1',ratings:R,images:D.map(g=>({category:g.key,items:g.items.map(it=>({id:it.id,title:it.title,source:it.url,license:it.license}))}))},null,2),'application/json');
el('csv').onclick=()=>{let lines=[['category','image','score','rank','fit','notes','url']];D.forEach(g=>g.items.forEach(it=>{let r=R[it.id]||{};lines.push([g.title,it.title,r.score??'',r.rank??'',r.fit??'',r.notes??'',it.url])}));let q=x=>'"'+String(x).replace(/"/g,'""')+'"';download('visible-mass-tlm-rankings.csv',lines.map(r=>r.map(q).join(',')).join('\n'),'text/csv')};draw();
</script></body></html>'''
out=Path('dist/visible-mass');out.mkdir(parents=True,exist_ok=True)
f=out/'Visible_Mass_TLM_Photo_Rating.html';f.write_text(page.replace('__PAYLOAD__',json.dumps(payload,ensure_ascii=False,separators=(',',':')).replace('</','<\\/')),encoding='utf8')
(out/'tlm-acquisition-report.json').write_text(json.dumps({'requested':len(names),'verified':total,'missing':missing,'categories':{g['key']:len(g['items']) for g in payload}},indent=2),encoding='utf8')
print('BUILT',f,f.stat().st_size,flush=True)
